def _clear(*names):
    for n in names:
        vars[n] = _empty(n)

def _money(x):
    try:
        return '%.2f' % float(x)
    except Exception:
        return _str(x)

def _fmt(iso):
    try:
        d = datetime.date.fromisoformat(_str(iso)[:10])
        return d.strftime('%A') + ' ' + str(d.day) + ' ' + d.strftime('%B %Y')
    except Exception:
        return _str(iso)

def _set_next(n):
    vars['next'] = n

def _offer_text(p, amount, date):
    return _money(amount) + ' for the ' + p['name'] + ' on ' + _fmt(date)

def st_finalize():
