        failed = [p for p in S['products'] if p.get('disposition') == (O.get('service_error_reason') or 'service_error') and (not p.get('paid'))]
        txt = 'Thank you. ' + ' '.join(parts) + ' ' + (POLICY['phrases'].get('after_promise_sentence') or '')
